# Generate elements of R = {11a + 20b | a, b >= 0} up to 21
R_small = set()
limit = 21
for a in range(limit // 11 + 1):
    for b in range(limit // 20 + 1):
        n = 11 * a + 20 * b
        if n <= limit:
            R_small.add(n)

print(f"R intersection with {{0, 1, ..., 21}}: {sorted(list(R_small))}")
print(f"Integers in {{0, 1, ..., 21}} not in R: {sorted(list(set(range(limit + 1)) - R_small))}")
